import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';
import 'dart:async';

void main() {
  runApp(const PttApp());
  }

  class PttApp extends StatelessWidget {
    const PttApp({super.key});

      @override
        Widget build(BuildContext context) {
            return MaterialApp(
                  title: 'PTT Application',
                        debugShowCheckedModeBanner: false,
                              theme: ThemeData.dark(),
                                    home: const PttHomeScreen(),
                                        );
                                          }
                                          }

                                          enum AppStatus { disconnected, connected, talking, receiving }

                                          class PttHomeScreen extends StatefulWidget {
                                            const PttHomeScreen({super.key});

                                              @override
                                                State<PttHomeScreen> createState() => _PttHomeScreenState();
                                                }

                                                class _PttHomeScreenState extends State<PttHomeScreen> {
                                                  final TextEditingController _codeController = TextEditingController();
                                                    AppStatus _status = AppStatus.disconnected;
                                                      String _serverIp = "";
                                                        int _maxDuration = 10;
                                                          Timer? _talkTimer;
                                                            int _currentTalkTime = 0;
                                                              bool _isLoading = false;

                                                                Future<void> _connectWithCode() async {
                                                                    if (_codeController.text.isEmpty) {
                                                                          _showMessage('الرجاء إدخال الكود أولاً');
                                                                                return;
                                                                                    }

                                                                                        setState(() => _isLoading = true);

                                                                                            try {
                                                                                                  final url = Uri.parse('http://192.168.1.100:8080/api/connect');
                                                                                                        final response = await http.post(
                                                                                                                url,
                                                                                                                        headers: {'Content-Type': 'application/json'},
                                                                                                                                body: jsonEncode({'code': _codeController.text}),
                                                                                                                                      ).timeout(const Duration(seconds: 5));

                                                                                                                                            if (response.statusCode == 200) {
                                                                                                                                                    final data = jsonDecode(response.body);
                                                                                                                                                            setState(() {
                                                                                                                                                                      _serverIp = data['ip'];
                                                                                                                                                                                _maxDuration = data['max_duration_seconds'] ?? 10;
                                                                                                                                                                                          _status = AppStatus.connected;
                                                                                                                                                                                                  });
                                                                                                                                                                                                          _showMessage('تم الضبط التلقائي للـ IP: $_serverIp');
                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                        _showMessage('الكود غير صحيح');
                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                  } catch (e) {
                                                                                                                                                                                                                                        setState(() {
                                                                                                                                                                                                                                                _serverIp = "192.168.1.50";
                                                                                                                                                                                                                                                        _maxDuration = 12;
                                                                                                                                                                                                                                                                _status = AppStatus.connected;
                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                            _showMessage('تم وضع الاتصال افتراضياً بالـ IP: $_serverIp');
                                                                                                                                                                                                                                                                                } finally {
                                                                                                                                                                                                                                                                                      setState(() => _isLoading = false);
                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                              void _startTalking() {
                                                                                                                                                                                                                                                                                                  if (_status != AppStatus.connected) return;

                                                                                                                                                                                                                                                                                                      setState(() {
                                                                                                                                                                                                                                                                                                            _status = AppStatus.talking;
                                                                                                                                                                                                                                                                                                                  _currentTalkTime = 0;
                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                          _talkTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
                                                                                                                                                                                                                                                                                                                                _currentTalkTime++;
                                                                                                                                                                                                                                                                                                                                      if (_currentTalkTime >= _maxDuration) {
                                                                                                                                                                                                                                                                                                                                              _stopTalking();
                                                                                                                                                                                                                                                                                                                                                      _showMessage('انتهت المهلة المحددة من المخدم ($_maxDuration ثانية)');
                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                    setState(() {});
                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                  void _stopTalking() {
                                                                                                                                                                                                                                                                                                                                                                                      _talkTimer?.cancel();
                                                                                                                                                                                                                                                                                                                                                                                          if (_status == AppStatus.talking) {
                                                                                                                                                                                                                                                                                                                                                                                                setState(() {
                                                                                                                                                                                                                                                                                                                                                                                                        _status = AppStatus.connected;
                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                      Color _getStatusColor() {
                                                                                                                                                                                                                                                                                                                                                                                                                          switch (_status) {
                                                                                                                                                                                                                                                                                                                                                                                                                                case AppStatus.disconnected:
                                                                                                                                                                                                                                                                                                                                                                                                                                        return Colors.orangeAccent;
                                                                                                                                                                                                                                                                                                                                                                                                                                              case AppStatus.connected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                      return Colors.green;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            case AppStatus.talking:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Colors.red;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          case AppStatus.receiving:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return Colors.blue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          String _getStatusText() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              switch (_status) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    case AppStatus.disconnected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "غير متصل - أدخل الكود وقم بالربط";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case AppStatus.connected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return "متصل وجاهز (IP: $_serverIp)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                case AppStatus.talking:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return "جاري الإرسال... (${_maxDuration - _currentTalkTime} ثانية متبقية)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              case AppStatus.receiving:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return "جاري استقبال صوت...";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              void _showMessage(String text) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  appBar: AppBar(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          title: const Text('تطبيق إضغط للتحدث PTT'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  centerTitle: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              body: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: const EdgeInsets.all(20.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Row(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Expanded(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        controller: _codeController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            keyboardType: TextInputType.number,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                decoration: const InputDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      labelText: 'مربع إدخال الكود',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            hintText: 'أدخل الكود الخاص بك',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  border: OutlineInputBorder(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(width: 10),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onPressed: _isLoading ? null : _connectWithCode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: ElevatedButton.styleFrom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: const EdgeInsets.symmetric(vertical: 20, horizontal: 15),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: _isLoading
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? const CircularProgressIndicator(color: Colors.white)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : const Text('إرسال الكود'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const SizedBox(height: 25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Container(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: double.infinity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: const EdgeInsets.all(15),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            color: _getStatusColor(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderRadius: BorderRadius.circular(10),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        _getStatusText(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        textAlign: TextAlign.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: const TextStyle(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: Colors.white,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fontWeight: FontWeight.bold,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fontSize: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const Spacer(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                GestureDetector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onTapDown: (_) => _startTalking(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onTapUp: (_) => _stopTalking(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onTapCancel: () => _stopTalking(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: AnimatedContainer(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        duration: const Duration(milliseconds: 150),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        width: 200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        height: 200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: _status == AppStatus.talking ? Colors.red : Colors.blueGrey[900],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            shape: BoxShape.circle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              border: Border.all(color: _getStatusColor(), width: 6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                boxShadow: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    BoxShadow(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: _getStatusColor().withOpacity(0.4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                blurRadius: 25,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      spreadRadius: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Icon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Icons.mic,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                size: 70,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color: _status == AppStatus.talking ? Colors.white : Colors.white70,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
